import {colors,weaponById,bounds} from './game.js';
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Could not load '+src));im.src=src;});}
// Generated atlases use a neutral checker matte. Remove only edge-connected
// matte during sprite upload; enclosed light hair and costume details stay intact.
function spriteCell(image,col,row,cols,rows,outW,outH){
 const w=Math.floor(image.width/cols),h=Math.floor(image.height/rows),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,Math.round(col*image.width/cols),Math.round(row*image.height/rows),w,h,0,0,w,h);
 const data=ctx.getImageData(0,0,w,h),d=data.data,seen=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;
 const push=i=>{if(i<0||i>=w*h||seen[i])return;seen[i]=1;const p=i*4,r=d[p],g=d[p+1],b=d[p+2];if(d[p+3]===0||(Math.max(r,g,b)-Math.min(r,g,b)<23&&Math.min(r,g,b)>138)){queue[tail++]=i;d[p+3]=0;}};
 for(let x=0;x<w;x++){push(x);push((h-1)*w+x);}for(let y=0;y<h;y++){push(y*w);push(y*w+w-1);}while(head<tail){const i=queue[head++],x=i%w;if(x>0)push(i-1);if(x<w-1)push(i+1);push(i-w);push(i+w);}ctx.putImageData(data,0,0);
 const out=document.createElement('canvas');out.width=outW;out.height=outH;const oc=out.getContext('2d');oc.imageSmoothingEnabled=false;oc.drawImage(canvas,0,0,outW,outH);return out;
}
export class Renderer {
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.assets=null;this.width=0;this.height=0;this.zoom=1.45;this.cam={x:768,y:512};this.resize();window.addEventListener('resize',()=>this.resize());}
 resize(){this.width=window.innerWidth;this.height=window.innerHeight;this.canvas.width=this.width;this.canvas.height=this.height;this.ctx.imageSmoothingEnabled=false;this.zoom=this.width<650?1.15:1.5;}
 async load(){const [characters,enemies,arena]=await Promise.all(['assets/characters.png','assets/enemies.png','assets/arena.png'].map(loadImage));this.assets={arena,characters:Array.from({length:5},(_,i)=>[spriteCell(characters,i,0,5,2,72,120),spriteCell(characters,i,1,5,2,72,120)]),enemies:Array.from({length:6},(_,i)=>spriteCell(enemies,i%3,Math.floor(i/3),3,2,80,80))};}
 portrait(index){const c=document.createElement('canvas');c.width=144;c.height=240;c.className='sprite';c.setAttribute('aria-hidden','true');const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(this.assets.characters[index][0],0,0,144,240);return c;}
 drawSprite(sprite,x,y,h,flip=false,alpha=1){const c=this.ctx,w=h*sprite.width/sprite.height;c.save();c.globalAlpha=alpha;c.translate(Math.round(x),Math.round(y));if(flip)c.scale(-1,1);c.drawImage(sprite,Math.round(-w/2),Math.round(-h+8),Math.round(w),Math.round(h));c.restore();}
 menu(){if(!this.assets)return;const c=this.ctx,scale=Math.max(this.width/1536,this.height/1024);c.fillStyle='#0a1923';c.fillRect(0,0,this.width,this.height);c.drawImage(this.assets.arena,(this.width-1536*scale)/2,(this.height-1024*scale)/2,1536*scale,1024*scale);}
 frame(g){if(!this.assets)return;if(!g){this.menu();return;}const c=this.ctx,z=this.zoom,w=this.width/z,h=this.height/z;this.cam.x=Math.max(w/2,Math.min(1536-w/2,g.x));this.cam.y=Math.max(h/2,Math.min(1024-h/2,g.y));if(w>1536)this.cam.x=768;if(h>1024)this.cam.y=512;
  c.setTransform(1,0,0,1,0,0);c.fillStyle='#081725';c.fillRect(0,0,this.width,this.height);c.save();c.scale(z,z);c.translate(Math.round(w/2-this.cam.x),Math.round(h/2-this.cam.y));
  c.drawImage(this.assets.arena,0,0);c.fillStyle='#06122055';c.fillRect(0,0,1536,1024);
  for(const p of g.pickups){c.save();c.translate(Math.round(p.x),Math.round(p.y));const bob=Math.round(Math.sin(g.time*3+p.x)*1.5);c.translate(0,bob);if(p.kind==='heal'){c.fillStyle='#87d99f';c.fillRect(-5,-2,10,4);c.fillRect(-2,-5,4,10);c.fillStyle='#d8f9d7';c.fillRect(-1,-3,2,6);}else{c.fillStyle=p.value>8?'#f3cf82':p.value>1?'#b69ded':'#72c7d2';c.beginPath();const r=p.value>8?6:4;c.moveTo(0,-r);c.lineTo(r,0);c.lineTo(0,r);c.lineTo(-r,0);c.closePath();c.fill();c.fillStyle='#ddffff';c.fillRect(-1,-2,2,2);}c.restore();}
  for(const hz of g.hazards){if(hz.triggered)continue;c.strokeStyle='#fc7999';c.fillStyle='#cd456b30';c.lineWidth=2;c.beginPath();c.arc(hz.x,hz.y,hz.r,0,Math.PI*2);c.fill();c.stroke();c.beginPath();c.arc(hz.x,hz.y,hz.r*(1-hz.timer/1.45),0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(hz.x-6,hz.y);c.lineTo(hz.x+6,hz.y);c.moveTo(hz.x,hz.y-6);c.lineTo(hz.x,hz.y+6);c.stroke();}
  const people=[...g.enemies.filter(e=>e.hp>0).map(e=>({e,y:e.y})),{player:true,y:g.y}].sort((a,b)=>a.y-b.y);
  for(const item of people){if(item.player){const idx=['ignara','nyxara','zephyra','amaris','naia'].indexOf(g.character.id),frame=g.moving?Math.floor(g.time*7)%2:0;const flicker=g.invuln>0&&Math.floor(g.time*20)%2===0;c.strokeStyle=g.character.color+'99';c.lineWidth=1.5;c.beginPath();c.ellipse(g.x,g.y+2,19,7,0,0,Math.PI*2);c.stroke();c.fillStyle='#00000055';c.beginPath();c.ellipse(g.x,g.y+2,14,5,0,0,Math.PI*2);c.fill();this.drawSprite(this.assets.characters[idx][frame],g.x,g.y,idx===4?81:76,Math.cos(g.dir)<-.2,flicker?.4:1);}
   else{const e=item.e;if(Math.abs(e.x-this.cam.x)>w/2+130||Math.abs(e.y-this.cam.y)>h/2+130)continue;const size=e.type==='final'?178:e.type==='mini'?105:52;const bob=Math.sin(e.age*(e.sprite>=3?7:5)+e.id)*1.5;c.fillStyle='#00000055';c.beginPath();c.ellipse(e.x,e.y+3,e.r+3,e.r*.3,0,0,Math.PI*2);c.fill();const sprite=e.type==='final'?this.assets.characters[4][Math.floor(e.age*4)%2]:this.assets.enemies[e.sprite];this.drawSprite(sprite,e.x,e.y+bob,size,e.x>g.x,e.flash>0?.58:1);if(e.slow>0){c.strokeStyle='#a9ecfc99';c.lineWidth=1;c.beginPath();c.ellipse(e.x,e.y,e.r+4,5,0,0,Math.PI*2);c.stroke();}if(e.burn>0){c.fillStyle='#ffa360';for(let i=0;i<3;i++)c.fillRect(Math.round(e.x+Math.sin(e.age*8+i*2)*e.r),Math.round(e.y-15-i*5),3,5);}if(e.type==='mini'){c.fillStyle='#251d2d';c.fillRect(e.x-30,e.y-size,60,4);c.fillStyle='#d8849e';c.fillRect(e.x-30,e.y-size,60*e.hp/e.maxHp,4);}}
  }
  for(const p of g.projectiles){c.save();c.translate(Math.round(p.x),Math.round(p.y));c.rotate(p.angle);c.fillStyle=p.color;if(p.element==='fire'){c.fillRect(-8,-3,14,6);c.fillRect(-3,-6,8,12);c.fillStyle='#fff2b8';c.fillRect(0,-3,6,6);c.fillStyle='#e46334';c.fillRect(-15,-2,7,4);}else if(p.element==='ice'){c.beginPath();c.moveTo(13,0);c.lineTo(-9,-5);c.lineTo(-5,0);c.lineTo(-9,5);c.closePath();c.fill();c.fillStyle='#e6feff';c.fillRect(-3,-1,10,2);}else{c.strokeStyle=p.color;c.lineWidth=3;c.beginPath();c.arc(-6,0,12,-1.1,1.1);c.stroke();}c.restore();}
  for(const fx of g.effects){const t=fx.life/fx.max;c.save();c.globalAlpha=Math.min(.9,t*1.6);c.strokeStyle=fx.color;c.fillStyle=fx.color+'24';c.lineWidth=3;
   if(fx.kind==='slash'){c.lineWidth=fx.element==='tide'?9:4;c.beginPath();c.arc(fx.x,fx.y,fx.r*(1-t*.14),fx.angle-fx.arc,fx.angle+fx.arc);c.stroke();c.lineWidth=1.5;c.strokeStyle='#f6eeed';c.beginPath();c.arc(fx.x,fx.y,fx.r*.83,fx.angle-fx.arc*.7,fx.angle+fx.arc*.7);c.stroke();}
   else if(fx.kind==='orbit'){c.translate(fx.x,fx.y);c.rotate(fx.angle+g.time*5);for(let i=0;i<3;i++){c.rotate(Math.PI*2/3);c.beginPath();c.arc(0,0,fx.r*.7,.1,1.4);c.stroke();}}
   else{const r=fx.r*(fx.kind==='ring'?1-t*.45:1-t*.2);c.beginPath();c.arc(fx.x,fx.y,r,0,Math.PI*2);c.fill();c.stroke();if(fx.kind==='strike'){for(let i=0;i<7;i++){const a=i*Math.PI*2/7;c.beginPath();c.moveTo(fx.x+Math.cos(a)*r*.7,fx.y+Math.sin(a)*r*.5);c.lineTo(fx.x+Math.cos(a)*r*.7,fx.y+Math.sin(a)*r*.5-r*t*.8);c.stroke();}}else{c.lineWidth=1;c.beginPath();c.arc(fx.x,fx.y,r*.76,0,Math.PI*2);c.stroke();}}
   c.restore();}
  for(const p of g.hostiles){c.fillStyle='#331829';c.beginPath();c.arc(p.x,p.y,p.r+2,0,Math.PI*2);c.fill();c.fillStyle=p.color;c.fillRect(Math.round(p.x-p.r),Math.round(p.y-p.r),p.r*2,p.r*2);c.fillStyle='#ffe2ef';c.fillRect(Math.round(p.x-1),Math.round(p.y-1),2,2);}
  c.textAlign='center';c.font='bold 11px monospace';for(const t of g.texts){c.globalAlpha=Math.min(1,t.life*3);c.fillStyle='#081016';c.fillText(t.text,t.x+1,t.y+1);c.fillStyle=t.color;c.fillText(t.text,t.x,t.y);}c.globalAlpha=1;
  // Show the direction to a living boss when it is outside the view.
  for(const e of g.enemies.filter(e=>e.type!=='mob'&&e.hp>0)){const dx=e.x-this.cam.x,dy=e.y-this.cam.y;if(Math.abs(dx)>w/2-60||Math.abs(dy)>h/2-85){const a=Math.atan2(dy,dx),ratio=Math.min((w/2-45)/Math.max(1,Math.abs(dx)),(h/2-95)/Math.max(1,Math.abs(dy)));const x=this.cam.x+dx*ratio,y=this.cam.y+dy*ratio;c.save();c.translate(x,y);c.rotate(a);c.fillStyle='#f099ae';c.beginPath();c.moveTo(8,0);c.lineTo(-5,-5);c.lineTo(-5,5);c.fill();c.restore();}}
  c.restore();if(g.invuln>.5){c.fillStyle='#b53b4422';c.fillRect(0,0,this.width,this.height);}
 }
}
